create extension if not exists pgcrypto;
create type public.order_status as enum ('new','accepted','preparing','ready','completed','cancelled','rejected');
create type public.order_type as enum ('dine_in','takeaway','delivery');
create table public.restaurants (
 id uuid primary key default gen_random_uuid(), name text not null, slug text not null unique,
 address text, phone text, maps_url text, opening_hours jsonb not null default '{}'::jsonb,
 currency text not null default 'INR', tax_percent numeric(5,2) not null default 0 check(tax_percent between 0 and 100),
 packaging_fee numeric(10,2) not null default 0 check(packaging_fee>=0), created_at timestamptz not null default now()
);
create table public.staff_memberships (
 id uuid primary key default gen_random_uuid(), restaurant_id uuid not null references public.restaurants(id) on delete cascade,
 user_id uuid not null references auth.users(id) on delete cascade, role text not null check(role in ('owner','manager','staff')),
 created_at timestamptz not null default now(), unique(restaurant_id,user_id)
);
create table public.menu_categories (
 id uuid primary key default gen_random_uuid(), restaurant_id uuid not null references public.restaurants(id) on delete cascade,
 name text not null, sort_order int not null default 0, active boolean not null default true
);
create table public.menu_items (
 id uuid primary key default gen_random_uuid(), restaurant_id uuid not null references public.restaurants(id) on delete cascade,
 category_id uuid references public.menu_categories(id) on delete set null, name text not null, description text not null default '',
 price numeric(10,2) not null check(price>=0), image_path text, is_veg boolean, available boolean not null default true,
 archived boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create table public.restaurant_tables (
 id uuid primary key default gen_random_uuid(), restaurant_id uuid not null references public.restaurants(id) on delete cascade,
 code text not null, label text not null, active boolean not null default true, unique(restaurant_id,code)
);
create table public.orders (
 id uuid primary key default gen_random_uuid(), order_number bigint generated by default as identity unique,
 restaurant_id uuid not null references public.restaurants(id), customer_name text not null, phone text not null,
 order_type public.order_type not null, table_id uuid references public.restaurant_tables(id), notes text,
 subtotal numeric(10,2) not null check(subtotal>=0), tax numeric(10,2) not null default 0 check(tax>=0), fees numeric(10,2) not null default 0 check(fees>=0),
 total numeric(10,2) not null check(total>=0), status public.order_status not null default 'new', payment_status text not null default 'unpaid' check(payment_status in ('unpaid','pending','paid','failed','refunded')),
 idempotency_key text unique, created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create table public.order_items (
 id uuid primary key default gen_random_uuid(), order_id uuid not null references public.orders(id) on delete cascade,
 menu_item_id uuid references public.menu_items(id) on delete set null, item_name text not null,
 quantity int not null check(quantity between 1 and 20), unit_price numeric(10,2) not null check(unit_price>=0), line_total numeric(10,2) not null check(line_total>=0),
 variant text, addons jsonb not null default '[]'::jsonb
);
create table public.payments (
 id uuid primary key default gen_random_uuid(), order_id uuid not null references public.orders(id) on delete cascade,
 provider text not null, provider_order_id text unique, provider_payment_id text unique, amount numeric(10,2) not null check(amount>=0), status text not null default 'pending', created_at timestamptz not null default now()
);
create table public.reservations (
 id uuid primary key default gen_random_uuid(), restaurant_id uuid not null references public.restaurants(id) on delete cascade,
 customer_name text not null, phone text not null, reservation_at timestamptz not null, guests int not null check(guests between 1 and 30),
 special_request text, status text not null default 'pending' check(status in ('pending','confirmed','rejected','cancelled','completed')), created_at timestamptz not null default now()
);
create index orders_restaurant_created_idx on public.orders(restaurant_id,created_at desc);
create index orders_status_idx on public.orders(restaurant_id,status,created_at desc);
create index menu_items_public_idx on public.menu_items(restaurant_id,available) where archived=false;
create index reservations_time_idx on public.reservations(restaurant_id,reservation_at);
-- Membership-based RLS foundation. Do not expose order PII to anonymous clients.
alter table public.restaurants enable row level security;
alter table public.staff_memberships enable row level security;
alter table public.menu_categories enable row level security;
alter table public.menu_items enable row level security;
alter table public.restaurant_tables enable row level security;
alter table public.orders enable row level security;
alter table public.order_items enable row level security;
alter table public.payments enable row level security;
alter table public.reservations enable row level security;
create policy "staff read own memberships" on public.staff_memberships for select to authenticated using(user_id=auth.uid());
create policy "staff read assigned restaurant" on public.restaurants for select to authenticated using(exists(select 1 from public.staff_memberships m where m.restaurant_id=id and m.user_id=auth.uid()));
create policy "staff manage assigned categories" on public.menu_categories for all to authenticated using(exists(select 1 from public.staff_memberships m where m.restaurant_id=menu_categories.restaurant_id and m.user_id=auth.uid())) with check(exists(select 1 from public.staff_memberships m where m.restaurant_id=menu_categories.restaurant_id and m.user_id=auth.uid()));
create policy "staff manage assigned menu" on public.menu_items for all to authenticated using(exists(select 1 from public.staff_memberships m where m.restaurant_id=menu_items.restaurant_id and m.user_id=auth.uid())) with check(exists(select 1 from public.staff_memberships m where m.restaurant_id=menu_items.restaurant_id and m.user_id=auth.uid()));
create policy "staff manage assigned tables" on public.restaurant_tables for all to authenticated using(exists(select 1 from public.staff_memberships m where m.restaurant_id=restaurant_tables.restaurant_id and m.user_id=auth.uid())) with check(exists(select 1 from public.staff_memberships m where m.restaurant_id=restaurant_tables.restaurant_id and m.user_id=auth.uid()));
create policy "staff read assigned orders" on public.orders for select to authenticated using(exists(select 1 from public.staff_memberships m where m.restaurant_id=orders.restaurant_id and m.user_id=auth.uid()));
create policy "staff read order items" on public.order_items for select to authenticated using(exists(select 1 from public.orders o join public.staff_memberships m on m.restaurant_id=o.restaurant_id where o.id=order_id and m.user_id=auth.uid()));
create policy "staff read assigned payments" on public.payments for select to authenticated using(exists(select 1 from public.orders o join public.staff_memberships m on m.restaurant_id=o.restaurant_id where o.id=order_id and m.user_id=auth.uid()));
create policy "staff manage reservations" on public.reservations for all to authenticated using(exists(select 1 from public.staff_memberships m where m.restaurant_id=reservations.restaurant_id and m.user_id=auth.uid())) with check(exists(select 1 from public.staff_memberships m where m.restaurant_id=reservations.restaurant_id and m.user_id=auth.uid()));
